learn=[('Locate the failure stage', 'Compare missing executable paths, failed startup, real process exits, native error results and application validation. Preserve each kind of evidence instead of treating every failure as an API outage.'), ('Read the native stream', 'Record message type and subtype, then inspect initialization model, tools, MCP servers, skills and plugin errors. Compare a raw result with any subsequent SDK exception.'), ('Capture useful diagnostics', 'Use the stderr callback, a temporary debugFile and actual getContextUsage summary. Redact credentials and leave raw API body logging disabled.'), ('Validate structured output', 'Native success alone does not guarantee the structured_output field. Check presence, configure a small compatible schema and permit the native StructuredOutput tool.'), ('Reproduce and fix', 'Six fault experiments reproduce a real SDK failure or application guard, then rerun the corrected configuration. A controlled Node CLI fixture demonstrates an actual process exit and stderr without faking a model failure.'), ('Route symptoms to the right topic', 'Use the symptom map for skills, MCP authentication, plugins, subagents, checkpoints, hooks and hosting. Keep Python-only startup distinctions separate from this TypeScript application.')]
labels=[('healthy', 'Healthy baseline · real Read task'), ('badpath', 'Missing executable · restore bundled CLI'), ('badstart', 'Invalid startup path · restore discovery'), ('exit', 'Controlled process exit · capture stderr'), ('invalidmodel', 'Invalid model · read native error report'), ('missing', 'Missing JSON · guard then configure schema'), ('structured', 'Valid structured output · simple schema'), ('turnlimit', 'Turn limit · preserve native error'), ('debug', 'Debug toolkit · file and context usage')]
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. On Windows, install Git Bash if the native CLI requires it. This lesson runs on the host; Docker and Managed Agents resource IDs are not required.', 'node --version\nnpm --version'), ('Install and configure', 'Preserve an existing .env, or copy the template. Enter your own API key privately in the same shell environment that starts the app. An inherited shell value takes precedence over the .env startup file.', 'cd .\\agent-sdk\\lesson50-troubleshooting\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open. Open the local URL and explore the five navigation pages. If the port is occupied, use the existing instance or change PORT and restart.', 'npm start\n# http://127.0.0.1:3150'), ('Reproduce startup and process failures', 'Missing and invalid executable overrides fail before a model call. The exit experiment uses a clearly labelled real Node transport fixture that prints stderr and exits with code seven. Every fault then runs the real model with corrected options.', 'npm run sample:env -- healthy\nnpm run sample:env -- badpath\nnpm run sample:env -- badstart\nnpm run sample:env -- exit'), ('Inspect results and required JSON', 'Invalid model preserves the raw result and the SDK error report after the colon. Missing JSON intentionally omits outputFormat, then fixes it; Structured requests a small real JSON schema.', 'npm run sample:env -- invalidmodel\nnpm run sample:env -- missing\nnpm run sample:env -- structured'), ('Inspect limits and the toolkit', 'Turn limit records the native error_max_turns before recovery. Debug captures a temporary CLI debug file and actual context usage. Download sanitized evidence, distinguish diagnostics from API responses, and run the offline checks.', 'npm run sample:env -- turnlimit\nnpm run sample:env -- debug\nnpm test')]
specs=[('Validate the classroom experiment', 'src/protocol.ts', 'if (', 'Only a fixed mode is accepted. Browser requests cannot inject arbitrary prompts, executable paths or tool definitions.', 0, 1, 7), ('Prepare separate attempt state', 'src/workspace.ts', 'async attempt(', 'Each attempt gets its own SDK home, config and debug file beneath a unique temporary workspace. A fictional note is the only permitted file.', 1, 1, 9), ('Select the model and limits', 'src/agent.ts', 'model:', 'Start from a known-good model and Read-only task. Fault modes deliberately change the model or turn allowance. JSON runs allow sufficient turns for Read and StructuredOutput.', 1, 1, 12), ('Capture actual stderr', 'src/agent.ts', 'stderr: (data)', 'The SDK stderr callback stores a bounded redacted tail and emits separate observations. Stderr is not an assistant answer and must not overwrite native messages.', 2, 1, 6), ('Choose the labelled startup fault', 'src/agent.ts', 'if (fault && c.mode === "badpath")', 'A missing path, directory override or controlled Node exit fixture exercises the actual SDK startup and transport. The corrected attempt removes these overrides.', 1, 1, 9), ('Request the JSON schema when needed', 'src/agent.ts', 'if (wantsJson && !(fault', 'Missing mode deliberately leaves outputFormat unset in its first attempt. Recovery supplies the small schema. This demonstrates an application guard, not an SDK defect.', 1, 1, 7), ('Start one real query per attempt', 'src/agent.ts', 'const run = query(', 'query starts the real SDK with the selected options. Consume the async stream and retain every observed type and subtype rather than guessing from visible text.', 1, 2, 12), ('Inspect initialization metadata', 'src/agent.ts', 'const summary = {', 'Read initialization model, tools, MCP servers, skills and plugin errors. An init message confirms startup, not successful task completion.', 2, 1, 11), ('Preserve native result fields', 'src/agent.ts', 'record.result = {', 'Keep the native subtype, session, stop reason, denials, estimate and structured-output presence. A raw success result can still be followed by an SDK error exception.', 2, 1, 10), ('Retain SDK exceptions separately', 'src/agent.ts', 'record.exception = {', 'TypeScript may throw an ordinary Error. Preserve its name and full redacted report separately from the raw result; the diagnostic classifier reads both.', 2, 1, 6), ('Require structured field presence', 'src/diagnostics.ts', 'if (result.structuredOutput === undefined)', 'A successful result without the requested field fails application validation. Presence is checked against undefined so valid false or zero values are not mistaken for absence.', 1, 3, 5), ('Read the native error report first', 'src/diagnostics.ts', 'if (/Claude Code returned an error result:/', 'The exception report after the colon takes priority even if a raw result says success. Keep process exit, startup and native error reports distinct; do not rewrite provider fields.', 3, 4, 10), ('Rerun the corrected configuration', 'src/agent.ts', 'if (fault && !controller.signal.aborted)', 'After a reproduced fault, make a fresh corrected attempt, verify the note is unchanged and publish independent recovery evidence. Finally remove only the unique temporary workspace.', 1, 4, 9)]
reference=[('Symptom map', 'Skills: Lesson 17; MCP authentication: 25; plugins: 20; subagents: 44; checkpoints: 42; hooks: 34; hosting: 48. This dashboard links those topics; it does not claim to reproduce every integration failure.'), ('Failure stages', 'Bad path and bad start use actual invalid executable overrides. Exit is a real Node child process fixture, not a real model process crash. Invalid model, turn limit and every corrected attempt use the actual bundled CLI and model service.'), ('Plain Error and native reports', 'TypeScript startup failures may be plain Error objects. Read the CLI report after Claude Code returned an error result:, preserve stderr and retain any raw result independently. The classifier never replaces the native status to make the UI look consistent.'), ('Python distinctions', 'The attached lesson also discusses Python native executable requirements on Windows and ClaudeSDKClient.connect(). This app is TypeScript; it does not claim to reproduce Python batch-file refusal or a missing Python client connection.'), ('Structured output', 'Success and field presence are independent checks. Missing mode deliberately omits outputFormat, then supplies a simple schema and permits StructuredOutput. A compatible small schema helps isolate a failure without promising every model or schema will succeed.'), ('Turn and spend limits', 'Read plus final output needs more than one turn. JSON can add a StructuredOutput call. SDK cost thresholds are estimates, not a hard prepaid spending cap. Authentication, model availability and provider credit can still prevent recovery.'), ('Debug privacy', 'Actual stderr, debug-file excerpts and context summaries can contain task text, paths or identifiers. This lab uses fictional notes, bounds its logs, redacts credentials and disables raw API body logging. Treat downloaded diagnostics as private; redaction is not comprehensive production DLP.'), ('Context and telemetry', 'Debug makes an actual getContextUsage summary call after the first assistant message. See Lesson 06 for context and compaction and Lesson 47 for OpenTelemetry. This lesson does not enable telemetry or raw HTTP bodies.'), ('Primary reference', 'https://code.claude.com/docs/en/agent-sdk/troubleshooting')]
body='<div class="flow"><div><b>01 · Configure</b><p>Select a diagnostic experiment</p></div><span>→</span><div><b>02 · Observe</b><p>Run the real SDK</p></div><span>→</span><div><b>03 · Verify</b><p>Inspect fault and recovery evidence</p></div></div><section class="panel" id="controls"><h2>Reproduce, diagnose and fix</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Diagnostic experiment</label><select id="mode"><option value="healthy">Healthy baseline · real Read task</option><option value="badpath">Missing executable · restore bundled CLI</option><option value="badstart">Invalid startup path · restore discovery</option><option value="exit">Controlled process exit · capture stderr</option><option value="invalidmodel">Invalid model · read native error report</option><option value="missing">Missing JSON · guard then configure schema</option><option value="structured">Valid structured output · simple schema</option><option value="turnlimit">Turn limit · preserve native error</option><option value="debug">Debug toolkit · file and context usage</option></select><button class="primary" id="run" disabled>Run diagnostic experiment →</button><p>Only a disposable fictional note is available to Read. Fault modes reproduce a labelled problem, then rerun corrected options. Normal tasks allow four turns; JSON allows eight. Each query uses a $0.30 SDK estimate threshold.</p></section><section class="step" id="specialists-panel"><h2>Actual diagnostic evidence</h2><div class="grid"><article class="card"><h3>Attempts</h3><p class="metric" id="span-count">0</p></article><article class="card"><h3>Native results</h3><p class="metric" id="metric-count">0</p></article><article class="card"><h3>Diagnosed failures</h3><p class="metric" id="log-count">0</p></article></div><p>A native result, SDK exception and application validation are separate evidence. Controlled startup and exit fixtures are labelled; corrected requests use the real model service.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Actual attempt configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div><section class="step" id="trace-panel"><h2>Attempt lifecycle</h2><p>Compare where each attempt stopped. Initialization confirms startup, while a native result and any later exception determine the diagnosis.</p><div class="table"><table><thead><tr><th>Attempt</th><th>Purpose</th><th>Actual source</th><th>Init messages</th><th>Native subtype</th><th>Diagnosis</th></tr></thead><tbody id="trace-history"></tbody></table></div></section><section class="step" id="metric-panel"><h2>Native SDK results</h2><p>Raw provider fields remain unchanged even when a later exception reports a model failure. SDK costs are estimates, not invoices.</p><div class="table"><table><thead><tr><th>Attempt</th><th>Session ID</th><th>Native subtype</th><th>Stop reason</th><th>JSON present</th><th>Estimate USD</th></tr></thead><tbody id="metric-history"></tbody></table></div></section><section class="step" id="model-panel"><h2>Diagnosis and next fix</h2><label for="user-filter">Filter by exact diagnosis category</label><input id="user-filter" placeholder="error-result"><p>Leave blank for all attempts, or use startup, process-exit, error-result, structured-output or success.</p><div class="table"><table><thead><tr><th>Attempt</th><th>Category</th><th>Observed report</th><th>Suggested fix</th></tr></thead><tbody id="log-history"></tbody></table></div></section><section class="step" id="results-panel"><h2>Native SDK result</h2><pre class="json-view"><code class="language-json" id="native-result">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Actual initialization and message sequence</h2><pre class="json-view"><code class="language-json" id="requests">{}</code></pre></section><section class="step" id="storage-panel"><h2>Recovery evidence and symptom map</h2><pre class="json-view"><code class="language-json" id="storage">{}</code></pre></section><section class="step" id="diagnostic-panel"><h2>Stderr, exceptions, debug file and context usage</h2><pre class="json-view"><code class="language-json" id="diagnostics">{}</code></pre></section><section class="step" id="observation-panel"><h2>Actual SDK observations · sanitized</h2><pre class="json-view"><code class="language-json" id="telemetry">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent actual run evidence</h2><pre class="json-view"><code class="language-json" id="evidence">{}</code></pre><button id="download">Download actual observations</button></section>'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3150\n# Windows only, if required:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'

document('/','Debug your agent. <em>Follow the evidence.</em>','Compare real startup faults, native error reports, JSON validation and corrected model calls.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Locate failures, inspect native diagnostics and demonstrate the fix.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your private .env</h2>'+snippet(env,'dotenv')+'<p>Keep the key private, restart after edits, and preserve an existing file. Existing shell values take precedence. If the port is occupied, change PORT.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install, configure privately and inspect the nine experiments.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','Agent SDK / CLI','Diagnostics','Evidence viewer']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='javascript' if source.endswith('.js') else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 50 · Reproduce → observe → diagnose → fix</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">Each attempt uses the real SDK transport. Startup and exit fixtures are explicitly labelled; native model requests, stderr and exceptions stay separate. The diagnostic classifier and evidence viewer are objects in the local host, not external deployed services. Numbered steps group alternative teaching paths.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked troubleshooting workflow steps"></div>'+walk)

document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has matching coloured TypeScript.',cards(reference)+walk)

readme='# Claude Agent SDK · Lesson 50 · Troubleshooting and debugging\n\nFive student pages, a real SDK diagnostic and recovery dashboard and thirteen source-linked UML code steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson50-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson50-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations: `cd .\\agent-sdk\\lesson50-troubleshooting`. Open http://127.0.0.1:3150. Node 24+, API credit and Windows Git Bash if needed.\n\n## Create your .env file\n\nCopy the template once and enter your own model key privately. Restart after edits. Existing shell values take precedence.\n\n```dotenv\n'+env+'```\n\nNo GitHub token, Docker or Managed Agents IDs are needed. On Windows, configure the optional Git Bash path only if required.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for s in steps:readme+=f'### {s["number"]}. {s["title"]}\n\n{s["explanation"]}\n\nSource: `{s["source"]}`, selected lines {s["firstLine"]}–{s["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{s["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## Validation\n\nRun `npm test` and `npm run build:client`. Regenerate pages with `python scripts/build-pages.py`. Secrets, dependencies, recordings and teaching media are excluded from Git.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
(PUBLIC/'style.css').write_text((PUBLIC/'style.css').read_text(encoding='utf-8')+'\n.metric{font-size:34px;font-weight:800}.json-view{max-height:380px}.table{max-height:420px;overflow:auto}td{min-width:140px;max-width:500px;overflow-wrap:anywhere}.markdown-body{font-size:22px;line-height:1.65}#conversation{max-height:450px;overflow:auto}input{width:100%;font:inherit;padding:16px;border:1px solid var(--line);border-radius:14px;color:var(--ink);background:var(--paper)}\n',encoding='utf-8')
print('Built five Lesson 50 pages with 13 coloured workflow snippets.')
